// CORREÇÃO ERRO 03: Parser da resposta da OpenAI + Guardrail e Fallback determinístico
// Extrai subject, text_body e html_body do JSON retornado pelo LLM e mescla com os dados do cliente.

const clientesOriginais = $("Code in JavaScript2").all();
const respostasIA = $input.all();

const saida = respostasIA.map((item, idx) => {
  const base = clientesOriginais[idx]?.json ?? item.json ?? {};
  const rawObj = item.json ?? {};

  // Localiza o texto retornado pelo nó Message a model (OpenAI) em diferentes formatos de saída
  const rawText =
    rawObj?.message?.content ??
    rawObj?.output ??
    rawObj?.text ??
    rawObj?.choices?.[0]?.message?.content ??
    (typeof rawObj?.content === "string" ? rawObj.content : "");

  let parsed = null;
  let modo_geracao = "ia_generativa_openai";

  if (rawText && typeof rawText === "string") {
    try {
      const limpo = rawText
        .replace(/```json/gi, "")
        .replace(/```/g, "")
        .trim();
      parsed = JSON.parse(limpo);
    } catch (e) {
      parsed = null;
    }
  }

  const fallbackSubject = `Recomendação de Investimento (${base.perfil}): ${base.recomendacao}`;
  const fallbackText =
    base.mensagem_base ||
    `Olá, ${base.nome}! Com base no seu perfil ${base.perfil} e saldo de ${base.saldo_texto}, sugerimos conhecer o produto ${base.recomendacao}. ${base.motivo} Lembre-se: investimentos possuem riscos e rentabilidade passada não representa garantia de resultados futuros.`;
  const fallbackHtml = `<p>Olá, <strong>${base.nome}</strong>!</p><p>${fallbackText}</p><p><em>Aviso legal: Esta comunicação tem caráter meramente informativo e não constitui promessa ou garantia de rentabilidade.</em></p>`;

  if (!parsed || !parsed.subject || (!parsed.text_body && !parsed.html_body)) {
    modo_geracao = "fallback_template_seguro";
    parsed = {
      subject: fallbackSubject,
      text_body: fallbackText,
      html_body: fallbackHtml
    };
  }

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const email_valido = emailRegex.test(String(base.email_to || "").trim());

  return {
    json: {
      email_to: String(base.email_to || "").trim(),
      email_valido,
      nome: base.nome,
      perfil: base.perfil,
      saldo_texto: base.saldo_texto,
      saldo_num: base.saldo_num,
      recomendacao: base.recomendacao,
      motivo: base.motivo,
      subject: String(parsed.subject).trim(),
      text_body: String(parsed.text_body || fallbackText).trim(),
      html_body: String(parsed.html_body || fallbackHtml).trim(),
      modo_geracao
    }
  };
});

return saida;
